def is_balanced(s):
    """
    Return True if every '(', '[', and '{' in the string is closed by the matching
    bracket in the correct order; otherwise return False.
    """
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
```

