def number_to_words(n: int) -> str:
    """
    Convert an integer 0 <= n <= 999 to its English words representation.
    All letters are lowercase, hyphens are used only between tens and ones
    (e.g., "twenty-one"). No "and" is included.
    """
    if not (0 <= n <= 999):
        raise ValueError("n must be between 0 and 999 inclusive")

    ones = [
        "zero", "one", "two", "three", "four",
        "five", "six", "seven", "eight", "nine"
    ]
    teens = [
        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty",
        "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def two_digit(num: int) -> str:
        if num < 10:
            return ones[num]
        if 10 <= num < 20:
            return teens[num - 10]
        ten, one = divmod(num, 10)
        if one == 0:
            return tens[ten]
        return f"{tens[ten]}-{ones[one]}"

    # Hundreds place
    hundred, rem = divmod(n, 100)
    if hundred == 0:
        return two_digit(rem)
    if rem == 0:
        return f"{ones[hundred]} hundred"
    return f"{ones[hundred]} hundred {two_digit(rem)}"
```

