def min_coins(coins, amount):
    """
    Returns the minimum number of coins needed to make exactly `amount` using unlimited
    supply of denominations in `coins`. Returns -1 if impossible. `amount` == 0 returns 0.
    """
    if amount < 0:
        return -1
    # Initialize DP array where dp[i] = min coins to make i, INF for unreachable
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        if coin <= 0:
            continue  # ignore non-positive denominations
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1

    return dp[amount] if dp[amount] != INF else -1
