def longest_common_prefix(strs):
    """
    Returns the longest common prefix among all strings in the list `strs`.
    If the list is empty or there is no common prefix, returns an empty string.
    """
    if not strs:
        return ""
    # Find the shortest string to limit the maximum possible prefix length
    shortest = min(strs, key=len)
