def is_sorted(xs):
    """
    Return True if the iterable xs is in non-decreasing order.
    An empty list or a single-element list is considered sorted.
    """
    # Convert to a sequence if possible to allow indexing; otherwise iterate pairwise.
    try:
        # Fast path for sequences supporting len and indexing
        n = len(xs)
        if n <= 1:
            return True
        for i in range(1, n):
            if xs[i] < xs[i - 1]:
                return False
        return True
    except TypeError:
        # Fallback for generic iterables
        it = iter(xs)
        try:
            prev = next(it)
        except StopIteration:
            return True  # empty iterable
        for cur in it:
            if cur < prev:
                return False
            prev = cur
        return True
