def word_wrap(text, width):
    if width < 1:
        raise ValueError("width must be a positive integer")
    words = text.split()
    if not words:
        return []
    lines = []
    current = ""
    for word in words:
        if not current:
            candidate = word
        else:
            candidate = current + " " + word
        if len(candidate) <= width:
            current = candidate
        else:
            if current:
                lines.append(current)
            # A word longer than width gets its own line
            if len(word) > width:
                lines.append(word)
                current = ""
            else:
                current = word
    if current:
        lines.append(current)
    return lines
