def word_wrap(text, width):
    """
    Greedily wrap words of `text` into lines of at most `width` characters.

    Words are joined with single spaces. A word longer than `width` gets
    its own line. Returns a list of lines; empty list if there are no words.
    """
    if width <= 0:
        raise ValueError("width must be a positive integer")

    words = text.split()
    if not words:
        return []

    lines = []
    current = []

    for word in words:
        if len(word) > width:
            # Flush current line first, then give the long word its own line.
            if current:
                lines.append(" ".join(current))
                current = []
            lines.append(word)
        elif not current:
            current = [word]
        elif len(current) + 1 + len(word) <= width:
            current.append(word)
        else:
            lines.append(" ".join(current))
            current = [word]

    if current:
        lines.append(" ".join(current))

    return lines
```

