def lcs_length(a, b):
    if not a or not b:
        return 0

    # Keep the DP rows as short as possible.
    if len(b) > len(a):
        a, b = b, a

    previous = [0] * (len(b) + 1)

    for char_a in a:
        current = [0] * (len(b) + 1)
        for j, char_b in enumerate(b, start=1):
            if char_a == char_b:
                current[j] = previous[j - 1] + 1
            else:
                current[j] = max(previous[j], current[j - 1])
        previous = current

    return previous[-1]
